package com.newland.nsdk.core.api.external.display;

/**
 * The position of the external display direction.
 */
public enum AlignType {
    /**
     * Default position in a line.
     */
    DEFAULT,
    /**
     * The left position in a line.
     */
    LEFT,
    /**
     * The center position in a line.
     */
    CENTER,
    /**
     * The right position in a line.
     */
    RIGHT
}


